  "backend/landungen/TEST.yaml": "# Nur für Engine-Tests: kurze, hindernisfreie Strecke, um Sieg-/Verlust-\n# Logik ohne Zufallseinfluss durch Flugzeuge/Kollisionen durchzuskripten.\ncode: TEST\nbezeichnung: Testflughafen (hindernisfrei)\n\n# Kein echter Flughafen - taucht daher nicht in der Flughafen-Auswahl im\n# Frontend auf (siehe backend/landung.py: flughafen_liste()). Über\n# Spielplan(\"TEST\") bzw. Landung(\"TEST\") bleibt er trotzdem ganz normal\n# nutzbar (siehe tests/test_engine.py).\nsichtbar: false\n\nmodule: null\nfaehigkeitskarten: 0\n\nschwierigkeit: 0\nlaenge: 3\nneuwurf_hoehen: [6000, 2000]\n\nflugzeuge_wuerfel_kurven_min_max:\n- 0 0 -2 2\n- 0 0 -2 2\n- 0 0 -2 2\n",
